(53, 0, 'Mr. Sonu Abhinandan Kumar', 'mr-sonu-abhinandan-kumar', '', '<p>Mr. Sonu Abhinandan Kumar is the Vice President and Business Head â€“ SMB at ApnaTime Tech Pvt. Ltd. He has over 20 years of experience and is an alumnus of IIM Lucknow.</p>', 'branch/assets/board/img1752751971.webp', 3, 0),
(54, 0, 'Mr. Kuldeep Dhama', 'mr-kuldeep-dhama', '', '<p>Kuldeep Dhama is a global technology leader with 25+ years of experience, including 15+ years in the USA. He has served as CTO at Curitics Health (USA), Country Head at RxAdvance (USA), and Head of Department at Blue Cross Blue Shield (USA), and has completed Executive Leadership programs at Harvard University campus focused on building leaders and high-performance teams.</p>', 'branch/assets/board/img1768201138.webp', 1, 0),
(55, 0, 'Prof. Nishchal Verma', 'prof-nishchal-verma', '', '<p>Nishchal Verma have 30 Years experience worked asÂ  Senior Vice President - Sales at Tata Play Ltd, a leading DTH service provider in India. He\'s had a stellar career, previously serving as Vice President - Service and General Manager - Sales Operations at Tata Play. Before joining Tata Play, he worked with Onida and INFRES METHODEX PVT. LTD.</p>', 'branch/assets/board/img1768203371.webp', 2, 0);

