INSERT INTO `category` (`id`, `c_name`, `c_type`, `c_url`, `c_desc`, `sdesc`, `featured_img`, `meta_title`, `meta_keywords`, `meta_desc`, `card_heading`, `card_data`, `section_heading`, `status`, `order`) VALUES
(1, 'About Us', '4', 'about-us-old', '<p>Sunrise Learning welcomes you and your family to a special school with an active-learning social environment. Its USP is the unique, secure and relaxed setting, where caring, sharing and cuddling are all significant parts of our daily activities. Sunrise Learning appreciates your confidence and trust, and hopes to partner with you and your family as we attempt to develop your ward ‘s Social, Emotional, Cognitive, Intellectual and Physical well-being along with you.</p>\r\n<p><strong>Some of our principles and approaches are inspired by the Son-Rise Program (Autism Treatment Center of America, MA, USA).</strong> Just like any other person, even people with autism are on a continuum/ spectrum of being really interactive at one point of time in the day, and being very withdrawn or disconnected at another moment. And since Autism is a social-relational condition, many autistics tend to be more on the disconnected end of the spectrum, for more time. So, their social/ interactive state can be said to be towards the RED end of the spectrum, (when they are completely disconnected) OR towards GREEN end (when they are willing to interact). We utilize these RED & GREEN lights to respect the social state of mind of the student, INTERACT with them accordingly and train the parents to identify these lights. So during red lights, we can simply Join their world, to BOND, while during green lights, we can teach, learn, and play. That helps us in entering their bubble, inside their world. It is a way of accepting these people, with a non-judgmental attitude. And this approach helps to develop a stronger bond and connection between the teachers and the students, thus facilitating better learning outcomes. “Happiness is a choice”, is yet another principle that we follow and teach at Sunrise Learning. We choose to be proud, grateful and happy for everything that we accomplish each day.</p>\r\n<p><strong>OUR APPROACH </strong></p>\r\n<p>Our Unique Value Proposition (USP): Lifespan Support for Neurodiverse Learners At Sunrise Learning, our core strength lies in providing holistic, lifespan-based support for individuals with autism and other developmental challenges. Unlike conventional approaches that compartmentalize services across different stages and institutions, we offer a seamless continuum of care and education — all under one roof. What a neurotypical individual typically receives through four distinct systems across their life — preschool, school, college, and professional training — a neurodiverse learner at Sunrise Learning experiences in an integrated, personalized journey that adapts to their pace, needs, and potential.</p>', '<p>Sunrise Learning welcomes you and your family to a special school with an active-learning social environment. Its USP is the unique, secure and relaxed setting, where caring, sharing and cuddling are all significant parts of our daily activities. Sunrise Learning appreciates your confidence and trust, and hopes to partner with you and your family as we attempt to develop your ward ‘s Social, Emotional, Cognitive, Intellectual and Physical well-being along with you</p>', '', '', '', '', NULL, NULL, NULL, 1, 1),
(2, 'S L Foundation', '1', 's-l-foundation', '<p>We are a not-for-profit non-Government organization dedicated towards providing employment, empowerment, inclusion, independence-Vocational training, education and support services to differently-abled people and their families.</p>\n<p>The organization is registered as a Trust, under The Indian Trusts Act, 1882 and NITI Aayog, DARPAN, FCRA, CSR-1.</p>\n<p>It is also registered under section 80G and 12A of Income Tax Act, 1961.</p>\n<p>With a head-office in New Delhi and a Special School at Noida, the Foundation works with families pan India through various out-reach programs for providing direct therapeutic support and Vocational Training to differently abled persons.</p>', '', 'branch/assets/category/img1788350626.webp', '', '', '', 'We support neurodiverse persons from ages 2 to 30+ years with our twin pillars:', '[{\"title\":\"SUNRISE LEARNING\",\"desc\":\"A school for Autism & Special Needs at NOIDA, which has 150+ students enrolled under multiple programs that address progressive and multifaceted learning.\"},{\"title\":\"OUT-REACH SUPPORT PROGRAM \\u2013 PAN-INDIA\",\"desc\":\"A multidimensional online program for student and parent empowerment that supports over 3000 families of neurodiverse persons.\"},{\"title\":\"MISSION\",\"desc\":\"Creating a cosmos of integrated solutions and holistic growth for neurodiverse children and young adults by providing education and livelihood readiness skills and empowering their families by building awareness and providing behaviour management and skill building support. Creating and nurturing opportunities of awareness, acceptance, acknowledgement and inclusion.\"}]', 'About Sunrise Learning Foundation', 1, 2),
(3, 'Parent Training', '1', 'parent-training', '<p class=\"parent-lead-quote\">\"People will walk in and walk out of a child\'s life. But a parent will stay.\"</p>\r\n<p class=\"parent-lead-quote highlight\">\"Therefore, a parent is the BEST RESOURCE PERSON for a child with autism\"</p>', 'People will walk in and walk out of a child\'s life. But a parent will stay. Therefore, a parent is the BEST RESOURCE PERSON for a child with autism', 'branch/assets/category/img1788427114.webp', '', '', '', '', '[]', 'Parents Training', 1, 2),
(4, 'Clinical Services', '1', 'clinical-services', '', '', 'branch/assets/category/img1788429093.webp', '', '', '', '', '[]', '', 1, 4),
(5, 'Upcoming Events', '1', 'upcoming-events', '', '', '', '', '', '', NULL, NULL, NULL, 1, 5),
(6, 'Online courses', '1', 'online-courses', '', '', '', '', '', '', '', '[]', '', 1, 6),
(7, 'Admission', '1', 'admission', '<div class=\"iqac-content\">\r\n    <h3>Admission Process</h3>\r\n\r\n    <ul class=\"iqac-stucture\">\r\n\r\n        <li>\r\n            <span>Program Admission: </span>\r\n            Admission is done either in the Intervention Program (EIP/GIP) or in the School Program (ELC/SLP/ICAN/VTC/ERT/GES).\r\n        </li>\r\n\r\n        <li>\r\n            <span>Eligibility Criteria: </span>\r\n            Admission is based on specific eligibility criteria. An assessment protocol helps the Sunrise Learning team determine the eligibility of each child.\r\n        </li>\r\n\r\n        <li>\r\n            <span>Program Selection: </span>\r\n            Once the student is found eligible for admission, the appropriate program is decided based on the age, skill level, independence, and adaptability of the child/adult.\r\n        </li>\r\n\r\n        <li>\r\n            <span>Waiting List: </span>\r\n            In case there is no vacancy in the appropriate program, the student is placed on the waiting list. Once a vacancy becomes available, the admission process proceeds further.\r\n        </li>\r\n\r\n        <li>\r\n            <span>Intervention or Trial Period: </span>\r\n            Depending on the student\'s functional status and ability to cope, the student may be given a slot for intervention with a parent or offered a trial period of 4–12 weeks.\r\n        </li>\r\n\r\n        <li>\r\n            <span>Final Admission Decision: </span>\r\n            After the trial period, a discussion is conducted between the team and the parents. This helps both the team and the parents make an informed decision regarding the admission and the appropriate program for the student.\r\n        </li>\r\n\r\n    </ul>\r\n</div>', '', '', '', '', '', '', '[{\"title\":\"ADMISSION WITH SCHOLARSHIP\",\"desc\":\"If at any point of time a parent goes through a financial difficulty and would like to apply for a scholarship support for the ward, they are welcome to submit the SCHOLARSHIP FORM. Scholarships are provided to students who either belong to disadvantaged families or with specific criteria. Scholarships are always granted subject to financial status of the organization and need & eligibility of the applicants (based on ITRs and family income). Decision of the scholarship committee is final and binding.  The scholarship will be withdrawn in case the Foundation management finds that the documents submitted by the parents for Scholarship are forged/false/fake.\"}]', '', 1, 9),
(8, 'Contact', '1', 'contact', '', '', '', '', '', '', NULL, NULL, NULL, 1, 10),
(9, 'News & Media', '2', 'news-media', '', '', '', '', '', '', NULL, NULL, NULL, 0, 15),
(13, 'Notice', '2', 'notice', '', '', '', '', '', '', NULL, NULL, NULL, 0, 16),
(18, 'Student Program', '1', 'student-program', '', '', '', '', '', '', NULL, NULL, NULL, 1, 2),
(20, 'IQAC Cell', '2', 'iqac-cell', '\r\n<div class=\"iqac-content\">\r\n    <h3>Our Integrated Learning Model</h3>\r\n\r\n    <ul class=\"iqac-stucture\">\r\n\r\n        <li>\r\n            <span>Early Intervention: </span>\r\n            Building communication, attention and foundational skills.\r\n        </li>\r\n\r\n        <li>\r\n            <span>Special Schooling: </span>\r\n            Individualised education, academics, communication and life skills.\r\n        </li>\r\n\r\n        <li>\r\n            <span>Pre-Vocational Development: </span>\r\n            Building practical, social and workplace skills.\r\n        </li>\r\n\r\n        <li>\r\n            <span>Vocational Skill Training: </span>\r\n            Training in computers, creative work, hospitality, retail and office skills.\r\n        </li>\r\n\r\n        <li>\r\n            <span>Employment & Livelihood Readiness: </span>\r\n            Preparing learners for employment, livelihood and independence.\r\n        </li>\r\n\r\n    </ul>\r\n</div>', '', '', '', '', '', '', '[]', '', 0, 1),
(25, 'CSR Social Activities', '2', 'csr-social-activities', '<div class=\"col-md-12\">\n<div class=\"innerbox\">\n<p>Empowering girls through education is a fantastic initiative. As Chairman Sh Vijayraj, KGI Meerut announced, providing maximum scholarships to fatherless girls is a great step towards promoting girls\' education.</p>\n<p>These scholarships can help support girls\' education and empower them to pursue their dreams. Great step taken by KGI Meerut for their initiative!</p>\n</div>\n</div>\n<div class=\"col-md-12\">\n<div class=\"innerbox\">\n<h3>Empowering Rural &amp; Semi-Urban Communities</h3>\n<p>Krishna Group of Institutions (KGI), Meerut, is dedicated to creating awareness about higher and professional education in rural and semi-urban areas.</p>\n</div>\n<div class=\"innerbox\">\n<h3>Initiatives:</h3>\n<ul>\n<li>Conducted over 100 seminars, sessions, and workshops in schools and colleges.</li>\n<li>Reached out to villages and semi-urban areas to promote employable education.</li>\n<li>Introduced economical fee structures and new-age, 21st-century employable certificate programs.</li>\n<li>Updated communities on government initiatives towards higher education.</li>\n</ul>\n</div>\n<div class=\"innerbox\">\n<h3>Impact:</h3>\n<ul>\n<li>Empowered parents to make informed decisions about their children\'s for Higher education.</li>\n<li>Inspired students to pursue higher education and career goals.</li>\n<li>Contributed to the development of rural and semi-urban communities.</li>\n</ul>\n</div>\n</div>', '', '', '', '', '', NULL, NULL, NULL, 0, 6),
(26, 'Photo Gallery', '2', 'photo-gallery', '<div class=\"innerbox\">\r\n    <h3>Transforming Lives Through Education &amp; Support</h3>\r\n    <p>\r\n        At Sunrise Learning, we are committed to empowering children, adolescents and adults with autism and other special needs. Through education, therapy, life-skill development and vocational training, we create opportunities for every individual to grow with confidence, independence and dignity.\r\n    </p>\r\n</div>\r\n\r\n<div class=\"innerbox\">\r\n    <h3>360-Degree Development</h3>\r\n    <p>\r\n        Our holistic approach focuses on the overall development of each learner. Along with academics, we work on communication, social skills, emotional development, self-care, physical fitness, creativity and functional abilities to help individuals participate meaningfully in everyday life.\r\n    </p>\r\n</div>\r\n\r\n<div class=\"innerbox\">\r\n    <h3>Learning Through Real-Life Experiences</h3>\r\n    <ul>\r\n        <li>Individualised education and developmental programs</li>\r\n        <li>Speech, communication and occupational therapy support</li>\r\n        <li>Life-skill and activities-of-daily-living training</li>\r\n        <li>Sports, yoga, dance, music, art and creative activities</li>\r\n        <li>Computer and technology-based learning</li>\r\n        <li>Practical and vocational skill development</li>\r\n    </ul>\r\n</div>\r\n\r\n<div class=\"innerbox\">\r\n    <h3>From Learning to Independence</h3>\r\n    <p>\r\n        Our programs are designed to help learners develop practical skills that can be used in real-world situations.\r\n    </p>\r\n    <ul>\r\n        <li>Build communication and social skills</li>\r\n        <li>Develop self-care and daily living skills</li>\r\n        <li>Improve confidence and self-expression</li>\r\n        <li>Discover individual strengths, interests and abilities</li>\r\n        <li>Develop pre-vocational and vocational skills</li>\r\n        <li>Prepare for employment, livelihood and greater independence</li>\r\n    </ul>\r\n</div>\r\n\r\n<div class=\"innerbox\">\r\n    <h3>Empowering Families &amp; Building Inclusion</h3>\r\n    <p>\r\n        At Sunrise Learning, parents and families are an important part of the learning journey. Through parent empowerment, guidance and school-home collaboration, we help families understand and support the unique needs of their loved ones while working together towards a more inclusive society.\r\n    </p>\r\n</div>\r\n\r\n<div class=\"innerbox\">\r\n    <p class=\"last\">\r\n        Together, we can create a more inclusive future where every individual is valued, respected and empowered to live with independence and dignity.\r\n    </p>\r\n</div>\r\n', '', '', '', '', '', '', '[]', '', 0, 7),
(30, 'Parent-Students Testimony', '2', 'parent-students-testimony', '', '', '', '', '', '', NULL, NULL, NULL, 0, 11),
(31, 'Feed Back', '2', 'feed-back', '', '', '', '', '', '', NULL, NULL, NULL, 0, 12),
(38, 'Blogs', '2', 'blogs', '', '', '', '', '', '', NULL, NULL, NULL, 0, 18),
(41, 'Sunrise  COE', '2', 'sunrise-coe', '<div class=\"faculty-container\"> <div class=\"container-lg\"> <div class=\"row\"> <div class=\"col-md-12\"> <div class=\"facultycontent\"> <div class=\"facultyinnercontent\"> <div class=\"facultytop\"> <h2>Sunrise Learning – Special School &amp; Vocational Training Centre</h2> <p> Sunrise Learning is a Special School and Vocational Training Centre in Noida, dedicated to supporting children, adolescents and adults with autism and other special needs. Since 2014, our focus has been on empowering neurodiverse individuals with education, therapy, life skills and vocational training so that they can move towards greater independence and dignity. </p> </div> <div class=\"facultymiddle\"> <h3>Our Vision &amp; Approach:</h3> <p> At Sunrise Learning, we believe that every individual has unique strengths, interests and potential. Our approach is designed around the needs of the learner rather than a one-size-fits-all model. We provide a safe, stimulating and nurturing environment where learners can develop their social, emotional, cognitive, communication, academic and physical abilities. </p> <h3>Lifespan Support for Neurodiverse Learners:</h3> <p> Our unique strength is our lifespan-based approach. We aim to provide continuity of support from early childhood through adolescence and adulthood, helping learners progress through different stages of education, skill development and employment readiness. Our integrated model includes early intervention, special schooling, pre-vocational development, vocational training and employment readiness. </p> <h3>Student Programs:</h3> <p> Sunrise Learning offers a range of programs designed for different age groups and developmental needs, including: </p> <ul> <li>Early Intervention for young children, focusing on foundational development, communication and sensory regulation</li> <li>Group Intervention and school-readiness programs for children developing communication, social and classroom participation skills</li> <li>Early Learning and Special Schooling with emphasis on functional academics, life skills and individual educational goals</li> <li>Pre-Vocational Programs that develop practical, social and work-related skills</li> <li>Vocational Skill Training in areas such as hospitality, retail, computers, arts and crafts and other interest-based activities</li> <li>Employment and Livelihood Readiness to prepare young adults for greater independence and supported employment opportunities</li> </ul> <h3>Therapy &amp; Skill Development:</h3> <p> Our multidisciplinary approach brings together special educators, psychologists, speech and language professionals, occupational therapists, autism specialists and other trained professionals. Programs may include speech and communication support, occupational therapy, sensory integration, activities of daily living, computer education, sports, yoga, dance, music, art and other developmental activities. </p> <h3>Parent Empowerment:</h3> <p> Parents are an essential part of a child\'s development. Sunrise Learning follows a School-Home Partnership approach and provides parent empowerment programs, guidance and skill-building support to help families understand their child\'s needs and become effective learning partners at home. Our outreach initiatives also extend support through online programs and awareness activities. </p> <h3>Building Independence &amp; Inclusion:</h3> <p> Our ultimate goal is to help neurodiverse children, young adults and their families move towards greater independence, dignity and inclusion. We focus on developing functional skills, communication, social participation, self-care, vocational abilities and confidence so that every learner can participate meaningfully in family, community and professional life. </p> <h3>Our Commitment:</h3> <p> At Sunrise Learning, we celebrate neurodiversity and focus on abilities, strengths and possibilities. Through education, therapy, vocational training, family empowerment and community awareness, we strive to create an inclusive environment where every individual is respected, supported and given the opportunity to reach their potential. </p> </div> </div> </div> </div> </div> </div> </div>', '', '', '', '', '', '', '[]', '', 0, 20),
(44, 'Gallery', '1', 'gallery', '', '', '', '', '', '', NULL, NULL, NULL, 1, 13),
