INSERT INTO `curriculum` (`id`, `type`, `title`, `url`, `desc`, `sdesc`, `file`, `author`, `order`, `date`, `status`, `metatitle`, `metakeywords`, `metadesc`) VALUES
(17, 0, 'Making of the RAM Setu', 'making-of-the-ram-setu', '<h2>Workshop on Leadership Skills and Team Building: \"Making of the RAM Setu\"</h2>\r\n<p>Krishna Group of Institutions (KGI), Meerut, organized a workshop on leadership skills and team building, inspired by the epic story of RAM Setu. The event was held on February 25th and witnessed enthusiastic participation from 180 UG and PG students.</p>\r\n<h3>Keynote Speaker</h3>\r\n<p>Prof. Dr. Devendra Arora, an esteemed alumnus of IIMC Kolkata, delivered a captivating session that left a lasting impact on the students. Dr. Arora\'s expertise and engaging teaching style made the workshop an unforgettable experience.</p>\r\n<h3>Workshop Highlights</h3>\r\n<p>The workshop began with a traditional Saraswati vandana, followed by a lamp-lighting ceremony attended by KGI Meerut\'s chairman, Vijayraj Kakaran, secretary, Pukhraj Singh, principal, Ms. Rajesh, and the keynote speaker.</p>\r\n<h3>Team-Based Learning</h3>\r\n<p>The workshop focused on team-based learning, where students were divided into teams of 5, accompanied by an auditor and an inventory manager. Each team was tasked with building a bridge, using raw materials provided. This exercise aimed to instill essential leadership qualities, such as:</p>\r\n<ul>\r\n<li>Teamwork</li>\r\n<li>Coordination</li>\r\n<li>Conflict handling</li>\r\n<li>Time management</li>\r\n<li>Financial budgeting</li>\r\n</ul>\r\n<h3>Learning Objectives</h3>\r\n<p>Through this interactive workshop, students learned valuable management tools and leadership skills inspired by Lord Rama\'s exemplary leadership. The workshop achieved its objectives, empowering students with essential skills to excel in their future endeavors.</p>\r\n<h3>Organizing Team</h3>\r\n<p>The success of the workshop was attributed to the tireless efforts of the organizing team, led by Ms. Mohini Sharma, coordinator, along with Shivansh, Amitesh, Kuldeep, Anushka and Shagun.</p>\r\n<p>KGI Meerut congratulates the students, faculty members, and the organizing team on the resounding success of the workshop.</p>', '<p>Krishna Group of Institutions (KGI), Meerut, organized a workshop on leadership skills and team building...</p>', 'branch/assets/curriculum/img1776838673.webp', '', '1', '', 1, '', '', ''),
(18, 0, 'Kala Mohotsva', 'kala-mohotsva', '<p>Activities play a vital role in enhancing confidence and nurturing creativity among students. The Department of Art at KGI, Meerut, successfully organized a vibrant Kala Mahotsav, providing a dynamic platform for students to showcase their artistic talents and innovative ideas.</p>\r\n<p>The event was thoughtfully coordinated by Kirti, Pratibha, and Rajesh Madam, whose dedication and guidance ensured its grand success. Students enthusiastically participated in various creative activities, expressing their imagination through art, culture, and performances.</p>\r\n<p>Kala Mahotsav not only celebrated artistic excellence but also encouraged self-expression, teamwork, and confidence-buildingâ€”key elements for holistic student development.</p>', '<p>Activities play a vital role in enhancing confidence and nurturing creativity...</p>', 'branch/assets/curriculum/img1777015882.webp', '', '2', '', 1, '', '', '');

