(1, 'Sunrise Learning', 'contactus@sunriselearning.in', 'admission@schoollearning.com', '8585928038', '7042979118', '', 'Plot No - SD 01, Sector 116 (Next to Sec 77) Noida, UP-201301   ', 'WhkiCZ7Xrc4               ', '<iframe src=\"https://www.google.com/maps/embed?pb=!1m17!1m12!1m3!1d3492.4767573962713!2d77.65849907551117!3d28.913892975512237!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m2!1m1!2zMjjCsDU0JzUwLjAiTiA3N8KwMzknMzkuOSJF!5e0!3m2!1sen!2sin!4v1724320192319!5m2!1sen!2sin\"  style=\"border:0;\" allowfullscreen=\"\" loading=\"lazy\" referrerpolicy=\"no-referrer-when-downgrade\"></iframe>', 'https://www.facebook.com/schoollearning', 'https://www.youtube.com/@schoollearning', 'https://www.instagram.com/schoollearning      ', '', 'https://www.linkedin.com/in/schoollearning', 'branch/assets/logo/logoImg1787999963.webp', 'Sunrise Learning - Special School Noida', 'Sun Rise Learning of School', 'SUNRISE LEARNING is a special school in Noida that offers school programs to children & adults with autism & other special needs.', '<div class=\"iqac-cotainer\">\r\n<div class=\"container-lg\">\r\n<div class=\"row\">\r\n<div class=\"col-md-12\">\r\n\r\n<div class=\"iqac-content\">\r\n    <h2>Technology-Enabled Learning at Sunrise Learning</h2>\r\n\r\n    <p>\r\n        At Sunrise Learning, technology is used as a supportive tool to make learning\r\n        more engaging, accessible and meaningful for children and young adults with\r\n        autism and other special needs.\r\n    </p>\r\n\r\n    <p>\r\n        Our technology-enabled learning environment supports individualised education,\r\n        communication, functional skills, digital learning and greater independence.\r\n    </p>\r\n</div>\r\n\r\n<div class=\"iqac-content\">\r\n    <h3>Features of Technology-Enabled Learning</h3>\r\n\r\n    <ul>\r\n        <li>\r\n            <span>Digital Learning:</span>\r\n            Use of computers and digital tools to support personalised learning.\r\n        </li>\r\n\r\n        <li>\r\n            <span>Interactive Activities:</span>\r\n            Multimedia and technology-based activities to make learning engaging.\r\n        </li>\r\n\r\n        <li>\r\n            <span>ICT Skills:</span>\r\n            Opportunities to develop basic computer and digital skills.\r\n        </li>\r\n\r\n        <li>\r\n            <span>Communication Support:</span>\r\n            Technology and AAC tools can support functional communication where required.\r\n        </li>\r\n\r\n        <li>\r\n            <span>Accessible Learning:</span>\r\n            Digital resources can be adapted according to individual learning needs.\r\n        </li>\r\n    </ul>\r\n</div>\r\n\r\n<div class=\"iqac-content\">\r\n    <h3>Benefits for Learners</h3>\r\n\r\n    <ul>\r\n        <li>Encourages interactive and engaging learning.</li>\r\n        <li>Supports individual learning styles and abilities.</li>\r\n        <li>Develops computer and digital skills.</li>\r\n        <li>Supports communication and functional learning.</li>\r\n        <li>Builds confidence and greater independence.</li>\r\n        <li>Prepares learners for future vocational opportunities.</li>\r\n    </ul>\r\n</div>\r\n\r\n<div class=\"iqac-content\">\r\n    <h3>Technology for Independence</h3>\r\n\r\n    <p>\r\n        Technology at Sunrise Learning goes beyond academic learning. Learners are\r\n        encouraged to use digital tools for communication, education, creativity,\r\n        everyday activities and vocational skill development.\r\n    </p>\r\n\r\n    <p>\r\n        By introducing technology according to individual abilities and needs, we aim\r\n        to help learners become more confident, capable and prepared for an increasingly\r\n        digital world.\r\n    </p>\r\n</div>\r\n\r\n<div class=\"iqac-content\">\r\n    <h3>Our Vision</h3>\r\n\r\n    <p>\r\n        Our vision is to create an inclusive learning environment where technology\r\n        supports every learner in developing skills, confidence and independence.\r\n    </p>\r\n\r\n    <p>\r\n        We believe that meaningful use of technology can open new opportunities for\r\n        learning, communication, creativity, vocational development and participation\r\n        in society.\r\n    </p>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>', '1st Smart Classroom', 'branch/images/brochure_1788931594.pdf', 'SUNRISE LEARNING is a special school in Noida that offers school programs to children & adults with autism & other special needs.', '<!-- Google tag (gtag.js) -->\r\n<script async src=\"https://www.googletagmanager.com/gtag/js?id=G-9GFT6R24ZS\"></script>\r\n<script>\r\n  window.dataLayer = window.dataLayer || [];\r\n  function gtag(){dataLayer.push(arguments);}\r\n  gtag(\'js\', new Date());\r\n\r\n  gtag(\'config\', \'G-9GFT6R24ZS\');\r\n</script>', 'Education for a Brighter Tomorrow');

