INSERT INTO `sub_cat` (`id`, `cat_id`, `sc_name`, `sc_url`, `sc_desc`, `sdesc`, `features`, `featured_img`, `featured_img1`, `meta_title`, `meta_keywords`, `meta_desc`, `status`, `order`) VALUES
(49, '18', 'Early Intervention Program ( EIP)', 'early-intervention-program-eip', '<div id=\"eip-program\" class=\"eip-program-section\">\n<div class=\"container-lg\">\n<div class=\"widgethead text-center\"><span class=\"sec-badge\">#StudentProgram</span>\n<h1 class=\"sec-main-heading\">EARLY INTERVENTION PROGRAM (EIP)</h1>\n<div class=\"eip-divider\">&nbsp;</div>\n<p class=\"sec-sub-title\">Foundational&nbsp; of multidisciplinary learning and therapeutic intervention for young neurodiverse learners</p>\n</div>\n<div class=\"row g-4\">\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-0\">\n<div><span class=\"eip-card-badge\">Target Age</span>\n<h3 class=\"eip-card-title\">For children aged 2 to 6 years</h3>\n<p class=\"eip-card-desc\">Specialized developmental and foundational early learning program designed specifically for young learners in their crucial developmental years.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-1\">\n<div><span class=\"eip-card-badge\">Frequency</span>\n<h3 class=\"eip-card-title\">3 days a week &amp; 5 days a week</h3>\n<p class=\"eip-card-desc\">Flexible attendance options (3-day or 5-day weekly schedule) tailored to suit the child\'s learning pace, energy levels, and family schedule.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-2\">\n<div><span class=\"eip-card-badge\">Timings</span>\n<h3 class=\"eip-card-title\">2 hours program Between 9 am to 1 pm</h3>\n<p class=\"eip-card-desc\">Focused 2-hour daily sessions conducted between morning hours (9:00 AM to 1:00 PM) to ensure maximum attention, routine predictability, and comfort.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-3\">\n<div><span class=\"eip-card-badge\">Dual Coaching</span>\n<h3 class=\"eip-card-title\">Therapeutic intervention for Child + parent</h3>\n<p class=\"eip-card-desc\">Active collaborative model involving both child and parents to practice behavior regulation, communication techniques, and home-school synchronization.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-4\">\n<div><span class=\"eip-card-badge\">Core Foundation</span>\n<h3 class=\"eip-card-title\">1:1 and group learning for FOUNDATION SKILLS</h3>\n<p class=\"eip-card-desc\">Targeted individual and social group learning addressing name response, functional communication, sitting tolerance, joint attention, and compliance.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-5\">\n<div><span class=\"eip-card-badge\">Therapy Spectrum</span>\n<h3 class=\"eip-card-title\">Multidisciplinary Therapies &amp; Activities</h3>\n<p class=\"eip-card-desc\">Special Education, Speech &amp; Language Therapy, Occupational Therapy, Sensory Integration Therapy, sensory-motor play, and structured indoor/outdoor social events.<br /><br /></p>\n</div>\n</div>\n</div>\n</div>\n</div>\n</div>', '', '', '', '', '', '', '', 1, 1),
(50, '18', 'EARLY LEARNING CENTER (ELC)', 'early-learning-center-elc', '<div id=\"elc-program\" class=\"eip-program-section\">\n<div class=\"container-lg\">\n<div class=\"widgethead text-center\"><span class=\"sec-badge\">#StudentProgram</span>\n<h1 class=\"sec-main-heading\">EARLY LEARNING CENTER (ELC)</h1>\n<div class=\"eip-divider\">&nbsp;</div>\n<p class=\"sec-sub-title\">Developmental learning and therapeutic school program for children aged 4 to 10 years</p>\n</div>\n<div class=\"row g-4 justify-content-center\">\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-0\">\n<div><span class=\"eip-card-badge\">Target Age</span>\n<h3 class=\"eip-card-title\">For children aged 4 to 10 years</h3>\n<p class=\"eip-card-desc\">Specialized learning and developmental support structured specifically for early learners aged 4 to 10 years.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-1\">\n<div><span class=\"eip-card-badge\">Frequency</span>\n<h3 class=\"eip-card-title\">5 days a week</h3>\n<p class=\"eip-card-desc\">Comprehensive regular weekday attendance (Monday to Friday) building consistent routines and peer socialization.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-2\">\n<div><span class=\"eip-card-badge\">Program Timings</span>\n<h3 class=\"eip-card-title\">School program - 9 am to 1 pm</h3>\n<p class=\"eip-card-desc\">Structured 4-hour daily schooling schedule combining academic engagement with integrated therapeutic interventions.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-6 col-md-6\">\n<div class=\"eip-feature-card card-eip-3\">\n<div><span class=\"eip-card-badge\">Basic Skills Foundation</span>\n<h3 class=\"eip-card-title\">Group learning for BASIC SKILLS</h3>\n<p class=\"eip-card-desc\">Participating in school independently without parents, self-feeding/eating, toileting, functional communication, sitting tolerance, compliance, and joint attention.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-6 col-md-12\">\n<div class=\"eip-feature-card card-eip-4\">\n<div><span class=\"eip-card-badge\">Multidisciplinary Curriculum</span>\n<h3 class=\"eip-card-title\">Therapies, Pre-Academics &amp; Social Activities</h3>\n<p class=\"eip-card-desc\">Special Education for pre-academics, Speech &amp; Language Therapy, Occupational Therapy &amp; Sensory Integration Therapy, Sports, Pre-Computer, group activities, sensory-motor play &amp; indoor/outdoor social events.</p>\n</div>\n</div>\n</div>\n</div>\n</div>\n</div>', '', '', '', '', '', '', '', 1, 2),
(53, '18', 'SKILL LEARNING PROGRAM (SLP)', 'skill-learning-program-slp', '<div id=\"slp-program\" class=\"eip-program-section\">\n<div class=\"container-lg\">\n<div class=\"widgethead text-center\"><span class=\"sec-badge\">#StudentProgram</span>\n<h1 class=\"sec-main-heading\">SKILL LEARNING PROGRAM (SLP)</h1>\n<div class=\"eip-divider\">&nbsp;</div>\n<p class=\"sec-sub-title\">Individualized skill learning, academic development, and sensory support for children aged 6 to 12 years</p>\n</div>\n<div class=\"row g-4\">\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-0\">\n<div><span class=\"eip-card-badge\">Target Age</span>\n<h3 class=\"eip-card-title\">For children aged 6 to 12 years</h3>\n<p class=\"eip-card-desc\">Comprehensive childhood schooling program designed for primary and middle school-aged children with special learning needs.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-1\">\n<div><span class=\"eip-card-badge\">Frequency</span>\n<h3 class=\"eip-card-title\">5 days a week</h3>\n<p class=\"eip-card-desc\">Regular weekday learning schedule providing predictable routines, structured classroom learning, and rich peer interaction.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-2\">\n<div><span class=\"eip-card-badge\">Timings</span>\n<h3 class=\"eip-card-title\">School program - 9 am to 1 pm</h3>\n<p class=\"eip-card-desc\">Morning sessions from 9:00 AM to 1:00 PM integrating classroom academic instruction with multi-disciplinary therapeutic interventions.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-3\">\n<div><span class=\"eip-card-badge\">Pedagogy</span>\n<h3 class=\"eip-card-title\">Learning through SIL Model</h3>\n<p class=\"eip-card-desc\">Active learning mapped to each student\'s Strengths, Interests, and Learning Style (SIL) to spark curiosity and organic engagement.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-4\">\n<div><span class=\"eip-card-badge\">Therapeutic Support</span>\n<h3 class=\"eip-card-title\">Special Education &amp; Integrated Therapies</h3>\n<p class=\"eip-card-desc\">Speech and Language Therapy, Occupational Therapy, Sensory Integration Diet, and Pre-Academic foundation learning.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-5\"><span class=\"eip-card-badge\">Co-Curricular</span>\n<h3 class=\"eip-card-title\">Sports, Computer &amp; Social Play</h3>\n<p class=\"eip-card-desc\">Computer literacy classes, sports competitions, sensory-motor active play, and indoor/outdoor educational social events.<br /><br /><strong>Computer Lab<br /><br /></strong>sbxjhabsjbxskb&nbsp; kjabskjxkas</p>\n</div>\n</div>\n</div>\n</div>\n</div>', '', '', '', '', '', '', '', 1, 5),
(69, '18', 'PRE-VOCATIONAL PROGRAMS', 'pre-vocational-programs', '<div id=\"pre-vocational-programs\" class=\"eip-program-section\">\n<div class=\"container-lg\">\n<div class=\"widgethead text-center\"><span class=\"sec-badge\">#StudentProgram</span>\n<h1 class=\"sec-main-heading\">PRE-VOCATIONAL PROGRAMS</h1>\n<div class=\"eip-divider\">&nbsp;</div>\n<p class=\"sec-sub-title\">Empowering adolescent learners aged 8 to 16 years with advance life skills, functional academics, and vocational exposure</p>\n</div>\n<div class=\"row g-4\">\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-0\">\n<div><span class=\"eip-card-badge\">Target Age</span>\n<h3 class=\"eip-card-title\">For adolescent children aged 8 to 16 years</h3>\n<p class=\"eip-card-desc\">Designed specifically for transitioning adolescent learners to prepare them for pre-vocational readiness and independence.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-1\">\n<div><span class=\"eip-card-badge\">Frequency</span>\n<h3 class=\"eip-card-title\">5 days a week</h3>\n<p class=\"eip-card-desc\">Regular weekday schooling structure establishing strong routines, peer relationships, and consistent learning progression.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-2\">\n<div><span class=\"eip-card-badge\">Timings &amp; Batches</span>\n<h3 class=\"eip-card-title\">School program with skill training</h3>\n<p class=\"eip-card-desc\">Flexible batch timings available: 9:00 AM to 1:00 PM or extended full-day program 9:00 AM to 4:00 PM.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-3\">\n<div><span class=\"eip-card-badge\">Pre-Advance Skills</span>\n<h3 class=\"eip-card-title\">Group learning for ADVANCE SKILLS</h3>\n<p class=\"eip-card-desc\">Personal safety and privacy awareness, social etiquette, consent, emotional regulation, functional communication, and behavior management.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-4\">\n<div><span class=\"eip-card-badge\">Education &amp; Sports</span>\n<h3 class=\"eip-card-title\">Special Education &amp; Movement Training</h3>\n<p class=\"eip-card-desc\">Functional and grade-level academic curriculum, sports and movement training for sensory integration, competitive events, and peer bonding.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-5\">\n<div><span class=\"eip-card-badge\">Vocational Tracks</span>\n<h3 class=\"eip-card-title\">Specific Skill Training Tracks</h3>\n<p class=\"eip-card-desc\">Hands-on skill labs in Computer basics, Creative Art Production, Caf&eacute; &amp; Hospitality, Retail Shoppe management, and Office administrative tasks.</p>\n</div>\n</div>\n</div>\n</div>\n</div>\n</div>', '', '', '', '', '', '', '', 1, 3),
(70, '18', 'VOCATIONAL TRAINING COURSES (VTC)', 'vocational-training-courses-vtc', '<div id=\"vtc-program\" class=\"eip-program-section\">\n<div class=\"container-lg\">\n<div class=\"widgethead text-center\"><span class=\"sec-badge\">#StudentProgram</span>\n<h1 class=\"sec-main-heading\">VOCATIONAL TRAINING COURSES (VTC)</h1>\n<div class=\"eip-divider\">&nbsp;</div>\n<p class=\"sec-sub-title\">College-equivalent of vocational training, employability skills, and independence for young adults aged 14 to 18+ years</p>\n</div>\n<div class=\"row g-4\">\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-0\">\n<div><span class=\"eip-card-badge\">Target Age</span>\n<h3 class=\"eip-card-title\">For young adults aged 14 to 18+ years</h3>\n<p class=\"eip-card-desc\">Comprehensive transition training bridging school education to adulthood, vocational certification, and livelihood readiness.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-1\">\n<div><span class=\"eip-card-badge\">Frequency</span>\n<h3 class=\"eip-card-title\">5 days a week</h3>\n<p class=\"eip-card-desc\">Intensive full weekday immersion instilling workplace discipline, punctuality, teamwork, and task completion habits.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-2\">\n<div><span class=\"eip-card-badge\">Timings &amp; Batches</span>\n<h3 class=\"eip-card-title\">School program with vocational skills</h3>\n<p class=\"eip-card-desc\">Flexible shift timings: Morning batch (9:00 AM to 1:00 PM) or Full-day intensive batch (9:00 AM to 4:00 PM).</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-3\">\n<div><span class=\"eip-card-badge\">Independence</span>\n<h3 class=\"eip-card-title\">Group learning for INDEPENDENCE SKILLS</h3>\n<p class=\"eip-card-desc\">Safety awareness in community, daily living independence, workplace etiquette, consent, emotional regulation, and self-advocacy.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-4\">\n<div><span class=\"eip-card-badge\">Academics &amp; Sports</span>\n<h3 class=\"eip-card-title\">Functional Academics &amp; Special Olympics</h3>\n<p class=\"eip-card-desc\">Special Education aligned with NIOS functional academics, alongside athletic and sports training for state and national Special Olympics.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-5\">\n<div><span class=\"eip-card-badge\">Industry Skills</span>\n<h3 class=\"eip-card-title\">Hands-on Vocational Specializations</h3>\n<p class=\"eip-card-desc\">Applied vocational training in Computers &amp; Data entry, Art Product manufacturing, Caf&eacute; baking &amp; service, Retail sales, and Office administration.</p>\n</div>\n</div>\n</div>\n</div>\n</div>\n</div>', '', '', '', '', '', '', '', 1, 4),
(71, '18', 'EMPLOYMENT READINESS TRAINING (ERT)', 'employment-readiness-training-ert', '<div id=\"ert-program\" class=\"eip-program-section\">\n<div class=\"container-lg\">\n<div class=\"widgethead text-center\"><span class=\"sec-badge\">#StudentProgram</span>\n<h1 class=\"sec-main-heading\">EMPLOYMENT READINESS TRAINING (ERT)</h1>\n<div class=\"eip-divider\">&nbsp;</div>\n<p class=\"sec-sub-title\">Professional livelihood coaching, workplace soft skills, and dignity training for adults aged 18+ years</p>\n</div>\n<div class=\"row g-4\">\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-0\">\n<div><span class=\"eip-card-badge\">Target Age</span>\n<h3 class=\"eip-card-title\">For adults aged 18+ years</h3>\n<p class=\"eip-card-desc\">Specialized adult livelihood program designed to nurture dignity, self-dependence, and professional competence in the real world.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-1\">\n<div><span class=\"eip-card-badge\">Schedule</span>\n<h3 class=\"eip-card-title\">5 days a week + select Saturdays</h3>\n<p class=\"eip-card-desc\">Immersive workplace schedule with weekday internships and project Saturdays simulating actual professional employment routines.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-2\">\n<div><span class=\"eip-card-badge\">Timings &amp; Batches</span>\n<h3 class=\"eip-card-title\">Livelihood Training Shifts</h3>\n<p class=\"eip-card-desc\">Flexible professional batch timings: 9:00 AM to 1:00 PM or extended full-day workday simulation 9:00 AM to 4:00 PM.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-3\">\n<div><span class=\"eip-card-badge\">Dignity &amp; Livelihood</span>\n<h3 class=\"eip-card-title\">Training for DIGNITY &amp; Autonomy</h3>\n<p class=\"eip-card-desc\">Individual and group coaching empowering adults to take pride in their work, earn stipends, and achieve supported independence.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-4\">\n<div><span class=\"eip-card-badge\">Workplace Soft Skills</span>\n<h3 class=\"eip-card-title\">Workplace Rules, Ethics &amp; Communication</h3>\n<p class=\"eip-card-desc\">Understanding written/email instructions, adapting to corporate work culture, authority compliance, task completion, and emotional self-regulation.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-5\">\n<div><span class=\"eip-card-badge\">Hard Skills &amp; Enterprise</span>\n<h3 class=\"eip-card-title\">Computer, Caf&eacute;, Retail &amp; Office Skills</h3>\n<p class=\"eip-card-desc\">Hands-on job training in Data entry &amp; Office IT, Creative Production manufacturing, Caf&eacute; bakery operations, and retail merchandises handling.</p>\n</div>\n</div>\n</div>\n</div>\n</div>\n</div>', '', '', '', '', '', '', '', 1, 6),
(72, '18', 'TRIAL PROGRAM (TP)', 'trial-program-tp', '<div id=\"trial-program\" class=\"eip-program-section\">\n<div class=\"container-lg\">\n<div class=\"widgethead text-center\"><span class=\"sec-badge\">#StudentProgram</span>\n<h1 class=\"sec-main-heading\">TRIAL PROGRAM (TP)</h1>\n<div class=\"eip-divider\">&nbsp;</div>\n<p class=\"sec-sub-title\">Initial interactive assessment and functional level evaluation for new students and families</p>\n</div>\n<div class=\"row g-4 justify-content-center\">\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-0\">\n<div><span class=\"eip-card-badge\">Duration</span>\n<h3 class=\"eip-card-title\">Initial 2-3 months of the school</h3>\n<p class=\"eip-card-desc\">Comprehensive trial window allowing the student to ease into the school environment comfortably without pressure.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-1\">\n<div><span class=\"eip-card-badge\">Timing</span>\n<h3 class=\"eip-card-title\">2 pm to 4 pm, with 1 parent</h3>\n<p class=\"eip-card-desc\">Afternoon sessions from 2:00 PM to 4:00 PM accompanied by one parent to ensure emotional security and joint observation.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-2\">\n<div><span class=\"eip-card-badge\">Interactive Evaluation</span>\n<h3 class=\"eip-card-title\">Multidisciplinary Faculty Assessments</h3>\n<p class=\"eip-card-desc\">Informal ongoing interactive assessments with educators, speech therapists, and occupational therapists to map functional levels.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-6 col-md-6\">\n<div class=\"eip-feature-card card-eip-3\">\n<div><span class=\"eip-card-badge\">Individual Profiling</span>\n<h3 class=\"eip-card-title\">Strengths &amp; Learning Style Mapping</h3>\n<p class=\"eip-card-desc\">Evaluating specific strengths, special interests, sensory triggers, and cognitive learning preferences to formulate a tailored developmental roadmap.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-6 col-md-12\">\n<div class=\"eip-feature-card card-eip-4\">\n<div><span class=\"eip-card-badge\">Program Placement</span>\n<h3 class=\"eip-card-title\">Functional Pathway Decision</h3>\n<p class=\"eip-card-desc\">Finalizing the optimal long-term school program, batch placement, and individualized educational plan (IEP) based on trial outcomes.</p>\n</div>\n</div>\n</div>\n</div>\n</div>\n</div>', '', '', '', '', '', '', '', 1, 8),
(73, '18', 'GROUP INTERVENTION PROGRAM (GIP)', 'group-intervention-program-gip', '<div id=\"gip-program\" class=\"eip-program-section\">\n<div class=\"container-lg\">\n<div class=\"widgethead text-center\"><span class=\"sec-badge\">#StudentProgram</span>\n<h1 class=\"sec-main-heading\">GROUP INTERVENTION PROGRAM (GIP)</h1>\n<div class=\"eip-divider\">&nbsp;</div>\n<p class=\"sec-sub-title\">Small-group intervention, school readiness, and multidisciplinary therapies for children aged 5 to 10 years</p>\n</div>\n<div class=\"row g-4\">\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-0\">\n<div><span class=\"eip-card-badge\">Target Age</span>\n<h3 class=\"eip-card-title\">For children aged 5 to 10 years</h3>\n<p class=\"eip-card-desc\">Specialized childhood group coaching designed to build classroom tolerance, peer interaction, and social integration.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-1\">\n<div><span class=\"eip-card-badge\">Frequency</span>\n<h3 class=\"eip-card-title\">5 days a week</h3>\n<p class=\"eip-card-desc\">Daily weekday sessions establishing structured schedules, social conditioning, and predictable group dynamics.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-2\">\n<div><span class=\"eip-card-badge\">Timings</span>\n<h3 class=\"eip-card-title\">2 hours program (2:30 to 4:30 pm)</h3>\n<p class=\"eip-card-desc\">Focused 2-hour afternoon program designed to transition children smoothly into structured group learning environments.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-3\">\n<div><span class=\"eip-card-badge\">Primary Goal</span>\n<h3 class=\"eip-card-title\">Target skill - School Readiness</h3>\n<p class=\"eip-card-desc\">Learning in small group formats addressing classroom sitting tolerance, attention span, instruction compliance, and peer sharing.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-4\">\n<div><span class=\"eip-card-badge\">Family Collaboration</span>\n<h3 class=\"eip-card-title\">Weekly Therapeutic Intervention</h3>\n<p class=\"eip-card-desc\">Joint Child + parent therapeutic intervention sessions equipping parents with real-time feedback and behavioral coping strategies.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-5\">\n<div><span class=\"eip-card-badge\">Comprehensive Spectrum</span>\n<h3 class=\"eip-card-title\">Special Education &amp; Active Sports</h3>\n<p class=\"eip-card-desc\">Speech &amp; Language Therapy, OT, Sensory Integration, sensory-motor play, sports including roller skating, and indoor/outdoor events.</p>\n</div>\n</div>\n</div>\n</div>\n</div>\n</div>', '', '', '', '', '', '', '', 1, 9),
(74, '18', 'SATURDAY SCHOOL', 'saturday-school', '<div id=\"saturday-school-program\" class=\"eip-program-section\">\n<div class=\"container-lg\">\n<div class=\"widgethead text-center\"><span class=\"sec-badge\">#WeekendProgram</span>\n<h1 class=\"sec-main-heading\">SATURDAY SCHOOL</h1>\n<div class=\"eip-divider\">&nbsp;</div>\n<p class=\"sec-sub-title\">Successfully running for 5+ years! A perfect weekend blend of learning, fun, and life skills for children aged 8+ years</p>\n</div>\n<div class=\"row g-4 justify-content-center\">\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-0\">\n<div><span class=\"eip-card-badge\">Timings</span>\n<h3 class=\"eip-card-title\">9:30 AM &ndash; 1:30 PM (4 Hours)</h3>\n<p class=\"eip-card-desc\">Four hours of structured learning, social development, and recreational fun designed to provide rich weekend engagement.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-1\">\n<div><span class=\"eip-card-badge\">Target Age</span>\n<h3 class=\"eip-card-title\">For children aged 8 years and above</h3>\n<p class=\"eip-card-desc\">Tailored specifically for specially-abled children aged 8 years and above seeking social interaction and practical growth.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-2\">\n<div><span class=\"eip-card-badge\">Independence</span>\n<h3 class=\"eip-card-title\">ADLs (Activities of Daily Living)</h3>\n<p class=\"eip-card-desc\">Focused on building essential daily living skills, personal grooming, table manners, independence, and self-advocacy.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-3\">\n<div><span class=\"eip-card-badge\">Skill Development</span>\n<h3 class=\"eip-card-title\">Pre-vocational Skills Training</h3>\n<p class=\"eip-card-desc\">Hands-on creative art production, sorting, packaging, and basic organizational tasks laying the foundation for future careers.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-4\">\n<div><span class=\"eip-card-badge\">Sensory Play</span>\n<h3 class=\"eip-card-title\">Sensory Integration through Play</h3>\n<p class=\"eip-card-desc\">Movement games, gross motor sports, sensory circuits, and recreational group play promoting regulation and joyful bonding.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-5\">\n<div><span class=\"eip-card-badge\">Special Workshop</span>\n<h3 class=\"eip-card-title\">Monthly Caf&eacute; Bakery Workshops</h3>\n<p class=\"eip-card-desc\">Interactive baking, sandwich making, table setup, and culinary hospitality workshops included monthly &ndash; practical, fun, and delicious!</p>\n</div>\n</div>\n</div>\n</div>\n</div>\n</div>', '', '', '', '', '', '', '', 1, 9),
(75, '18', 'EVENING SKILL PROGRAM', 'evening-skill-program', '<div id=\"evening-skill-program\" class=\"eip-program-section\">\n<div class=\"container-lg\">\n<div class=\"widgethead text-center\"><span class=\"sec-badge\">#AfterSchool</span>\n<h1 class=\"sec-main-heading\">EVENING SKILL PROGRAM</h1>\n<div class=\"eip-divider\">&nbsp;</div>\n<p class=\"sec-sub-title\">After-school skill enhancement, group communication, and real-life participation for specially-abled students 8 years &amp; above</p>\n</div>\n<div class=\"row g-4\">\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-0\">\n<div><span class=\"eip-card-badge\">Timings (Mon&ndash;Fri)</span>\n<h3 class=\"eip-card-title\">Flexible Evening Slots</h3>\n<p class=\"eip-card-desc\">Convenient weekday evening sessions: 4:00 &ndash; 6:00 PM (2-hour comprehensive), 4:00 &ndash; 5:00 PM, or 5:00 &ndash; 6:00 PM (1-hour slots).</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-1\">\n<div><span class=\"eip-card-badge\">Communication</span>\n<h3 class=\"eip-card-title\">Communication &amp; Group Language</h3>\n<p class=\"eip-card-desc\">Expressive language development, functional peer conversation, active listening, asking for help, and social interaction skills.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-2\">\n<div><span class=\"eip-card-badge\">Emotional Health</span>\n<h3 class=\"eip-card-title\">Social &amp; Emotional Regulation</h3>\n<p class=\"eip-card-desc\">Sensory integration, emotional de-escalation tools, stress management, self-soothing techniques, and positive behavior reinforcement.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-3\">\n<div><span class=\"eip-card-badge\">Social Dynamic</span>\n<h3 class=\"eip-card-title\">Group Participation &amp; Team Games</h3>\n<p class=\"eip-card-desc\">All sessions conducted in structured group settings to build real-life participation skills, turn-taking, cooperation, and friendship.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-4\">\n<div><span class=\"eip-card-badge\">Weekly Specials</span>\n<h3 class=\"eip-card-title\">Special Weekly Group Activities</h3>\n<p class=\"eip-card-desc\">Hands-on exposure within school premises including Caf&eacute; Class, Computer Lab Sessions, Sports Competitions, and Supermarket/Shop Visits.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-5\">\n<div><span class=\"eip-card-badge\">Progress Tracking</span>\n<h3 class=\"eip-card-title\">Monthly Assessments &amp; Reports</h3>\n<p class=\"eip-card-desc\">Regular progress evaluations conducted by faculty and detailed monthly progress reports shared transparently with parents.</p>\n</div>\n</div>\n</div>\n</div>\n</div>\n</div>', '', '', '', '', '', '', '', 1, 10),
(76, '18', 'SATURDAY INTERVENTION PROGRAM', 'saturday-intervention-program', '<div id=\"sip-program\" class=\"eip-program-section\">\n<div class=\"container-lg\">\n<div class=\"widgethead text-center\"><span class=\"sec-badge\">#TherapyProgram</span>\n<h1 class=\"sec-main-heading\">SATURDAY INTERVENTION PROGRAM</h1>\n<div class=\"eip-divider\">&nbsp;</div>\n<p class=\"sec-sub-title\">One-on-one specialized therapy and parent empowerment sessions designed especially for children aged 2 to 10 years</p>\n</div>\n<div class=\"row g-4 justify-content-center\">\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-0\">\n<div><span class=\"eip-card-badge\">Timings &amp; Age</span>\n<h3 class=\"eip-card-title\">Ages 2&ndash;10 Years | 10:30 AM &ndash; 1:30 PM</h3>\n<p class=\"eip-card-desc\">Personalized weekend intervention for children with Autism, ADHD, and Speech Delay conducted every Saturday by expert clinicians.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-1\">\n<div><span class=\"eip-card-badge\">1:1 Clinical Therapy</span>\n<h3 class=\"eip-card-title\">1:1 Speech &amp; Language Therapy (40 Mins)</h3>\n<p class=\"eip-card-desc\">Individualized speech pathology addressing oral motor skills, sound articulation, AAC communication, and receptive-expressive language.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-2\">\n<div><span class=\"eip-card-badge\">1:1 Occupational Therapy</span>\n<h3 class=\"eip-card-title\">1:1 Occupational Therapy (40 Mins)</h3>\n<p class=\"eip-card-desc\">Specialized sensory integration therapy, fine/gross motor exercises, posture regulation, body awareness, and sensory diet formulation.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-3\">\n<div><span class=\"eip-card-badge\">1:1 Special Education</span>\n<h3 class=\"eip-card-title\">1:1 Special Education (40 Mins)</h3>\n<p class=\"eip-card-desc\">Individual cognitive intervention, sitting tolerance, visual processing, academic readiness, and task compliance coaching.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-4\">\n<div><span class=\"eip-card-badge\">Parent Support</span>\n<h3 class=\"eip-card-title\">Live Q&amp;A &amp; Parent Empowerment</h3>\n<p class=\"eip-card-desc\">Direct interactive Q&amp;A sessions with the Sunrise Learning senior clinical team to address home struggles and progress tracking.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-5\">\n<div><span class=\"eip-card-badge\">Flexible Booking</span>\n<h3 class=\"eip-card-title\">Independent Session Booking</h3>\n<p class=\"eip-card-desc\">Flexible scheduling allows booking independent therapy packages or customized session frequencies matching your child\'s needs.</p>\n</div>\n</div>\n</div>\n</div>\n</div>\n</div>', '', '', '', '', '', '', '', 1, 11),
(77, '18', 'GROUP EVENING SCHOOL (GES)', 'group-evening-school-ges', '<div id=\"ges-program\" class=\"eip-program-section\">\n<div class=\"container-lg\">\n<div class=\"widgethead text-center\"><span class=\"sec-badge\">#StudentProgram</span>\n<h1 class=\"sec-main-heading\">GROUP EVENING SCHOOL (GES)</h1>\n<div class=\"eip-divider\">&nbsp;</div>\n<p class=\"sec-sub-title\">Afternoon&nbsp; of group schooling, academic progression, and therapeutic skill training for children &amp; adults aged 4 to 18+ years</p>\n</div>\n<div class=\"row g-4 justify-content-center\">\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-0\">\n<div><span class=\"eip-card-badge\">Target Age</span>\n<h3 class=\"eip-card-title\">For children &amp; adults aged 4 to 18+ years</h3>\n<p class=\"eip-card-desc\">Inclusive multi-age afternoon school catering to diverse learning stages, developmental milestones, and age brackets.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-1\">\n<div><span class=\"eip-card-badge\">Functional Batches</span>\n<h3 class=\"eip-card-title\">Batches Based on Functional Age</h3>\n<p class=\"eip-card-desc\">Students grouped by functional competency and learning pace across three distinct batches: Basic, Intermediate, and Advance.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-4 col-md-6\">\n<div class=\"eip-feature-card card-eip-2\">\n<div><span class=\"eip-card-badge\">Schedule</span>\n<h3 class=\"eip-card-title\">5 Days a Week (2:00 PM to 5:00 PM)</h3>\n<p class=\"eip-card-desc\">Three hours of daily afternoon schooling combining core classroom learning with integrated multi-disciplinary therapies.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-6 col-md-6\">\n<div class=\"eip-feature-card card-eip-3\">\n<div><span class=\"eip-card-badge\">Vocational Pathways</span>\n<h3 class=\"eip-card-title\">Therapeutic Intervention &amp; Vocational Skills</h3>\n<p class=\"eip-card-desc\">Therapeutic intervention along with individualized pre-vocational and vocational skill training customized to each learner\'s special needs.</p>\n</div>\n</div>\n</div>\n<div class=\"col-lg-6 col-md-12\">\n<div class=\"eip-feature-card card-eip-4\">\n<div><span class=\"eip-card-badge\">Curriculum &amp; Events</span>\n<h3 class=\"eip-card-title\">Special Education, Therapies &amp; Social Events</h3>\n<p class=\"eip-card-desc\">Special Education for academics, Speech &amp; Language, Occupational Therapy, Sensory Integration, Sports, Computer, sensory-motor play, and indoor/outdoor social events.</p>\n</div>\n</div>\n</div>\n</div>\n</div>\n</div>', '', '', '', '', '', '', '', 1, 12),
(79, '49', 'SL Canteen Cafe', 'sl-canteen-cafe', '<h1>🍽️ Sunrise Learning Canteen 🍽️</h1>\n<p>&nbsp;</p>\n<p>At Sunrise Learning Foundation, our canteen is more than just a place to enjoy meals &mdash; it is a space where our special students learn independence, responsibility, teamwork, and social interaction through everyday experiences. From serving food and maintaining cleanliness to interacting with peers and staff, each activity helps build confidence and life skills in a warm, supportive environment. 🌟</p>', '', '', '', '', '', '', '', 1, 1),
(80, '49', 'SL Shoppe', 'sl-shoppe', '<h1>At the Sunrise Learning Shoppe, learning becomes a real-life experience for our students. 🌈✨</h1>\n<p>&nbsp;</p>\n<p>Students from different programs actively visit the shoppe to purchase items, helping them understand important concepts such as identifying products, making choices, handling money, and completing transactions independently. Through this meaningful activity, they develop practical life skills, confidence, communication, and social interaction in a structured and supportive environment. 💙</p>\n<p>&nbsp;</p>\n<p>Every visit to the Shoppe is a step towards greater independence and real-world learning for our special learners. 🌟</p>', '', '', '', '', '', '', '', 1, 2),
(81, '49', 'SL Creative Production', 'sl-creative-production', '<h1>&nbsp;🌟 Creative Production &ndash; Sunrise Learning Shoppe 🌟</h1>\n<p>&nbsp;</p>\n<p>At Sunrise Learning Foundation, creativity becomes a pathway to confidence, skill-building, and independence. Through our Creative Production Unit, our special learners lovingly create a variety of handmade products that reflect their talent, dedication, and hard work.</p>\n<p>&nbsp;</p>\n<p>The Sunrise Learning Shoppe showcases these beautiful creations made in-house by our students and trainees as part of their vocational and employment readiness journey. From artistic crafts to thoughtfully designed products, every item carries a story of learning, growth, and empowerment.</p>\n<p>&nbsp;</p>\n<p>By supporting the Sunrise Learning Shoppe, you are not only encouraging creativity but also helping our learners move towards greater independence and meaningful opportunities.</p>\n<p>&nbsp;</p>\n<p><a href=\"../branch/pdf/Sunrise Learning Shoppe Catalog.pdf\" target=\"_blank\" rel=\"noopener\"> 📄 View Creative Production Catalogue (PDF) </a></p>', '', '', '', '', '', '', '', 1, 3);

