--
-- Table structure for table `testimonials`
--

CREATE TABLE `testimonials` (
  `id` int(11) NOT NULL,
  `category` varchar(255) NOT NULL,
  `title` text NOT NULL,
  `url` text NOT NULL,
  `desc` longtext NOT NULL,
  `file` varchar(255) NOT NULL,
  `order` varchar(255) NOT NULL,
  `status` int(255) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Dumping data for table `testimonials`
--

INSERT INTO `testimonials` (`id`, `category`, `title`, `url`, `desc`, `file`, `order`, `status`) VALUES
(1, '', 'vandana and amit', 'vandana-and-amit', '<p>When we approached Sunrise Learning in 2018, we knew only 2 things. First, our child Sarvika was on autism spectrum disorder and second it has no cure. Through the Mom and child programme, we came to understand the basics about the condition known as autism and how to approach the child . Later Sarvika joined the school in the EIP program. Slowly and steadily, little victories in the form of toilet training and sitting tolerance were achieved. The eating, sleeping, playing, doing activities</p>', '', '', 1),
(2, '', 'Rajiv', 'rajiv', '<p>When we approached Sunrise Learning in 2018, we knew only 2 things. First, our child Sarvika was on autism spectrum disorder and second it has no cure. Through the Mom and child programme, we came to understand the basics about the condition known as autism and how to approach the child. Later Sarvika joined the school in the EIP program. Slowly and steadily, little victories in the form of toilet training and sitting tolerance were achieved. The eating, sleeping, playing, doing activities.</p>', '', '2', 1),
(3, '', 'Sakshi m/o arnav arora', 'sakshi-m-o-arnav-arora', '<p>We are so grateful for the positive impact Sunrise Learning has had on our child\'s well-being. The school has created a safe and nurturing space where our child feels valued and respected. They have also learned valuable life skills that will help them succeed in the future,\" We love the sense of community at Sunrise Learning. The school embraces diversity and creates a welcoming environment for all students. We feel like we\'ve found a second family here,\"</p>', '', '3', 1),
(4, '', 'Seema Banathia', 'seema-banathia', '<p>We, parents of Aarushi Banathia, a student in Sunrise Learning, are overwhelmed with gratitude for the incredible progress our daughter has made at this special school (Sunrise Learning). Over the past year, our child has thrived, learning new skills and achieving milestones we never thought possible. Not only is she learning new skills, she is able to implement these skills in real-life situations. The school\'s tailored approach, using visual supports, social stories, and sensory considerations, has been instrumental in her development</p>', '', '4', 1),
(5, '', 'Vandana and Amit', 'vandana-and-amit', '<p>When we first joined Sunrise Learning, we knew it would be a place for Saksham. What we didn’t expect was for it to become an essential part of his and our lives. Over the years, Saksham has grown in ways we never thought possible. Sunrise Learning has been an integral part of our journey with Saksham. It is not just a school—it has been a nurturing ground where Saksham blossomed from a little child into a confident, expressive, and thoughtful 16-year-old teenager. Over the years, we have witnessed remarkable growth in every area of his development</p>', '', '5', 1),
(6, '', 'Rajiv', 'rajiv', '<p>When we approached Sunrise Learning in 2018, we knew only 2 things. First, our child Sarvika was on autism spectrum disorder and second it has no cure. Through the Mom and child programme, we came to understand the basics about the condition known as autism and how to approach the child. Later Sarvika joined the school in the EIP program. Slowly and steadily, little victories in the form of toilet training and sitting tolerance were achieved. The eating, sleeping, playing, doing activities.</p>', '', '6', 0);

